// Complete Roster HTML Builder with Code node - All Features Restored
const webhookData = $('Your WebPage').item.json || {};
const selectedDate = webhookData.query?.date || new Date(new Date().toLocaleString("en-US", {timeZone: "Asia/Kolkata"})).toISOString().split('T')[0];

// Use $input.all() to get roster data with proper Code node method
const rosterData = $input.all();

// Generate table rows with shift sorting and G shift toggle
let tableRows = '';
let employeeCount = 0;
let gShiftCount = 0;

if (rosterData && rosterData.length > 0) {
  // Filter out any empty/null entries
  const validData = rosterData.filter(item => item.json && item.json.employee_name);
  employeeCount = validData.length;

  if (validData.length > 0) {
    // Define shift priority order: A, AWH, B, BWH, WO, L, G
    const shiftPriority = {
      'A': 1,
      'AWH': 1.5,
      'B': 2,
      'BWH': 2.5, 
      'WO': 3,
      'L': 4,
      'G': 5
    };

    // Function to transform shift display names
    const getShiftDisplayName = (shift) => {
      const upperShift = (shift || '').toUpperCase();
      switch (upperShift) {
        case 'AWH':
          return 'A (WFH)';
        case 'BWH':
          return 'B (WFH)';
        default:
          return shift || 'N/A';
      }
    };

    // Sort data by shift priority
    const sortedData = validData.sort((a, b) => {
      const shiftA = (a.json.shift || 'unknown').toUpperCase();
      const shiftB = (b.json.shift || 'unknown').toUpperCase();

      const priorityA = shiftPriority[shiftA] || 999;
      const priorityB = shiftPriority[shiftB] || 999;

      return priorityA - priorityB;
    });

    // Separate G shift entries for toggle functionality
    const nonGShiftData = sortedData.filter(item => (item.json.shift || '').toUpperCase() !== 'G');
    const gShiftData = sortedData.filter(item => (item.json.shift || '').toUpperCase() === 'G');
    gShiftCount = gShiftData.length;

    // Function to get CSS class for shift badge
    const getShiftCssClass = (shift) => {
      const upperShift = (shift || 'unknown').toUpperCase();
      switch (upperShift) {
        case 'AWH':
          return 'shift-a';
        case 'BWH':
          return 'shift-b';
        default:
          return `shift-${shift.toLowerCase()}`;
      }
    };

    // Generate rows for non-G shifts
    let rowIndex = 1;
    tableRows = nonGShiftData.map((item) => {
      const data = item.json;
      return `<tr class="roster-row">
        <td class="row-number">${rowIndex++}</td>
        <td class="employee-name">${data.employee_name || 'N/A'}</td>
        <td class="shift-info">
          <span class="shift-badge ${getShiftCssClass(data.shift || 'unknown')}">
            ${getShiftDisplayName(data.shift)}
          </span>
        </td>
        <td class="contact-info">
          ${data.mobile ? `<a href="tel:${data.mobile}" class="phone-link">${data.mobile}</a>` : 'N/A'}
        </td>
        <td class="email-info">
          ${data.email ? `<a href="mailto:${data.email}" class="email-link">${data.email}</a>` : 'N/A'}
        </td>
      </tr>`;
    }).join('');

    // Add G shift toggle row if there are G shift entries
    if (gShiftCount > 0) {
      tableRows += `<tr class="g-shift-toggle-row">
        <td colspan="5" class="g-shift-toggle">
          <button class="toggle-g-shift" onclick="toggleGShift()">
            <span id="g-shift-icon">👁️</span>
            <span id="g-shift-text">Show G Shift (${gShiftCount} employees)</span>
          </button>
        </td>
      </tr>`;

      // Add G shift rows (hidden by default)
      tableRows += gShiftData.map((item) => {
        const data = item.json;
        return `<tr class="roster-row g-shift-row" style="display: none;">
        <td class="row-number">${rowIndex++}</td>
        <td class="employee-name">${data.employee_name || 'N/A'}</td>
        <td class="shift-info">
          <span class="shift-badge shift-g">
            ${getShiftDisplayName(data.shift)}
          </span>
        </td>
        <td class="contact-info">
          ${data.mobile ? `<a href="tel:${data.mobile}" class="phone-link">${data.mobile}</a>` : 'N/A'}
        </td>
        <td class="email-info">
          ${data.email ? `<a href="mailto:${data.email}" class="email-link">${data.email}</a>` : 'N/A'}
        </td>
      </tr>`;
      }).join('');
    }
  } else {
    tableRows = `<tr class="no-data-row">
      <td colspan="5" class="no-data">
        <div class="no-data-content">
          <span class="no-data-icon">📅</span>
          <div class="no-data-text">No roster data available</div>
          <div class="no-data-subtext">No employees are scheduled for this date</div>
        </div>
      </td>
    </tr>`;
  }
} else {
  tableRows = `<tr class="no-data-row">
    <td colspan="5" class="no-data">
      <div class="no-data-content">
        <span class="no-data-icon">📅</span>
        <div class="no-data-text">No roster data available</div>
        <div class="no-data-subtext">No employees are scheduled for this date</div>
      </div>
    </td>
  </tr>`;
}

// Format date for display
const formatDisplayDate = (dateStr) => {
  const date = new Date(dateStr);
  const options = { 
    weekday: 'short', 
    day: 'numeric', 
    month: 'short', 
    year: 'numeric' 
  };
  return date.toLocaleDateString('en-US', options);
};

// Calculate previous and next dates
const currentDate = new Date(selectedDate);
const prevDate = new Date(currentDate);
prevDate.setDate(currentDate.getDate() - 1);
const nextDate = new Date(currentDate);
nextDate.setDate(currentDate.getDate() + 1);

const prevDateStr = prevDate.toISOString().split('T')[0];
const nextDateStr = nextDate.toISOString().split('T')[0];
// Get current time in IST
const istTime = new Date().toLocaleString('en-IN', {
  timeZone: 'Asia/Kolkata',
  dateStyle: 'medium',
  timeStyle: 'medium'
});
const displayDate = formatDisplayDate(selectedDate);

// Complete HTML template with all features restored
const html = `<!DOCTYPE html>
<html lang="en">
<head>
    <meta charset="UTF-8">
    <meta name="viewport" content="width=device-width, initial-scale=1.0">
    <title>Technical Support Group (Roster)</title>
    <style>
        /* CSS Variables for Theme Support */
        :root {
            --bg-color: linear-gradient(135deg, #667eea 0%, #764ba2 100%);
            --card-bg: #ffffff;
            --text-primary: #333333;
            --text-secondary: #666666;
            --text-muted: #999999;
            --border-color: #e0e0e0;
            --hover-bg: rgba(0, 123, 255, 0.1);
            --accent-color: #007bff;
            --success-color: #28a745;
            --warning-color: #ffc107;
            --danger-color: #dc3545;
            --info-color: #17a2b8;
            --shadow: 0 8px 32px rgba(0, 0, 0, 0.1);
            --transition: all 0.3s cubic-bezier(0.4, 0, 0.2, 1);
        }

        [data-theme="dark"] {
            --bg-color: linear-gradient(135deg, #1a1a2e 0%, #16213e 50%, #0f3460 100%);
            --card-bg: #2d3748;
            --text-primary: #ffffff;
            --text-secondary: #e2e8f0;
            --text-muted: #a0aec0;
            --border-color: #4a5568;
            --hover-bg: rgba(66, 153, 225, 0.2);
            --accent-color: #4299e1;
            --shadow: 0 8px 32px rgba(0, 0, 0, 0.3);
        }

        * {
            margin: 0;
            padding: 0;
            box-sizing: border-box;
        }

        body {
            font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, Oxygen, Ubuntu, Cantarell, sans-serif;
            background: var(--bg-color);
            min-height: 100vh;
            color: var(--text-primary);
            transition: var(--transition);
            padding: 20px;
            line-height: 1.6;
        }

        .main-container {
            max-width: 1200px;
            margin: 0 auto;
            background: var(--card-bg);
            border-radius: 20px;
            box-shadow: var(--shadow);
            overflow: hidden;
            backdrop-filter: blur(10px);
            transition: var(--transition);
        }

        .header {
            background: var(--accent-color);
            color: white;
            padding: 30px;
            text-align: center;
            position: relative;
            background: linear-gradient(135deg, var(--accent-color) 0%, #6610f2 100%);
        }

        .theme-toggle {
            position: absolute;
            top: 20px;
            right: 20px;
            background: rgba(255, 255, 255, 0.2);
            border: none;
            border-radius: 50%;
            width: 50px;
            height: 50px;
            cursor: pointer;
            font-size: 24px;
            display: flex;
            align-items: center;
            justify-content: center;
            transition: var(--transition);
            backdrop-filter: blur(10px);
        }

        .theme-toggle:hover {
            background: rgba(255, 255, 255, 0.3);
            transform: scale(1.1);
        }

        .title {
            font-size: 2.2rem;
            font-weight: 700;
            margin-bottom: 20px;
            text-shadow: 0 2px 4px rgba(0, 0, 0, 0.3);
        }

        .date-navigation {
            display: flex;
            align-items: center;
            justify-content: center;
            gap: 20px;
            background: rgba(255, 255, 255, 0.15);
            padding: 15px 30px;
            border-radius: 50px;
            backdrop-filter: blur(10px);
            margin: 0 auto;
            max-width: 500px;
            flex-wrap: wrap;
        }

        .nav-button {
            background: rgba(255, 255, 255, 0.2);
            border: none;
            border-radius: 50%;
            width: 45px;
            height: 45px;
            cursor: pointer;
            display: flex;
            align-items: center;
            justify-content: center;
            transition: var(--transition);
            font-size: 18px;
            color: white;
        }

        .nav-button:hover {
            background: rgba(255, 255, 255, 0.3);
            transform: scale(1.1);
        }

        .nav-button:active {
            transform: scale(0.95);
        }

        .current-date {
            font-size: 1.3rem;
            font-weight: 600;
            color: #ff6b6b;
            text-shadow: 0 2px 4px rgba(0, 0, 0, 0.2);
            min-width: 150px;
            text-align: center;
        }

        .date-picker-container {
            display: flex;
            align-items: center;
            gap: 10px;
        }

        .date-picker {
            background: rgba(255, 255, 255, 0.2);
            border: 2px solid rgba(255, 255, 255, 0.3);
            border-radius: 25px;
            padding: 8px 15px;
            color: white;
            font-size: 14px;
            font-weight: 600;
            cursor: pointer;
            transition: var(--transition);
            backdrop-filter: blur(10px);
        }

        .date-picker:hover {
            background: rgba(255, 255, 255, 0.3);
            border-color: rgba(255, 255, 255, 0.5);
        }

        .date-picker::-webkit-calendar-picker-indicator {
            filter: invert(1);
            cursor: pointer;
        }

        .content {
            padding: 30px;
        }

        .summary-stats {
            display: grid;
            grid-template-columns: repeat(auto-fit, minmax(200px, 1fr));
            gap: 20px;
            margin-bottom: 30px;
        }

        .stat-card {
            background: linear-gradient(135deg, var(--accent-color), #6610f2);
            color: white;
            padding: 20px;
            border-radius: 15px;
            text-align: center;
            box-shadow: 0 4px 15px rgba(0, 123, 255, 0.3);
            transition: var(--transition);
        }

        .stat-card:hover {
            transform: translateY(-5px);
            box-shadow: 0 8px 25px rgba(0, 123, 255, 0.4);
        }

        .stat-number {
            font-size: 2rem;
            font-weight: 700;
            display: block;
        }

        .stat-label {
            font-size: 0.9rem;
            opacity: 0.9;
            margin-top: 5px;
        }

        .table-container {
            background: var(--card-bg);
            border-radius: 15px;
            overflow: hidden;
            box-shadow: 0 4px 20px rgba(0, 0, 0, 0.1);
            border: 1px solid var(--border-color);
        }

        .table {
            width: 100%;
            border-collapse: collapse;
        }

        .table thead {
            background: linear-gradient(135deg, var(--accent-color), #6610f2);
            color: white;
        }

        .table th {
            padding: 18px 15px;
            text-align: left;
            font-weight: 600;
            font-size: 0.95rem;
            letter-spacing: 0.5px;
            text-transform: uppercase;
        }

        .table td {
            padding: 15px;
            border-bottom: 1px solid var(--border-color);
            transition: var(--transition);
        }

        .roster-row {
            transition: var(--transition);
        }

        .roster-row:hover {
            background: var(--hover-bg);
            transform: scale(1.01);
        }

        .row-number {
            font-weight: 600;
            color: var(--accent-color);
            width: 60px;
        }

        .employee-name {
            font-weight: 600;
            color: var(--text-primary);
        }

        .shift-badge {
            padding: 6px 12px;
            border-radius: 20px;
            font-size: 0.85rem;
            font-weight: 600;
            text-transform: uppercase;
            letter-spacing: 0.5px;
        }

        .shift-morning {
            background: linear-gradient(135deg, #ff9a9e, #fecfef);
            color: #d63384;
        }

        .shift-evening {
            background: linear-gradient(135deg, #a8edea, #fed6e3);
            color: #0dcaf0;
        }

        .shift-a {
            background: linear-gradient(135deg, #ff9a9e, #fecfef);
            color: #d63384;
        }

        .shift-b {
            background: linear-gradient(135deg, #a8edea, #fed6e3);
            color: #0dcaf0;
        }

        .shift-night {
            background: linear-gradient(135deg, #d299c2, #fef9d7);
            color: #6f42c1;
        }

        .shift-g {
            background: linear-gradient(135deg, #c5c5c5, #e0e0e0);
            color: #495057;
        }



        .g-shift-toggle {
            text-align: center;
            padding: 20px;
            background: var(--hover-bg);
        }

        .toggle-g-shift {
            background: var(--accent-color);
            color: white;
            border: none;
            border-radius: 25px;
            padding: 10px 20px;
            cursor: pointer;
            font-size: 0.9rem;
            font-weight: 600;
            transition: var(--transition);
            display: flex;
            align-items: center;
            gap: 8px;
            margin: 0 auto;
        }

        .toggle-g-shift:hover {
            background: var(--success-color);
            transform: scale(1.05);
        }

        .phone-link, .email-link {
            color: var(--accent-color);
            text-decoration: none;
            transition: var(--transition);
            padding: 5px 10px;
            border-radius: 8px;
        }

        .phone-link:hover, .email-link:hover {
            background: var(--hover-bg);
            transform: scale(1.05);
        }

        .no-data {
            padding: 60px 20px;
            text-align: center;
        }

        .no-data-content {
            max-width: 300px;
            margin: 0 auto;
        }

        .no-data-icon {
            font-size: 3rem;
            display: block;
            margin-bottom: 15px;
        }

        .no-data-text {
            font-size: 1.2rem;
            font-weight: 600;
            color: var(--text-primary);
            margin-bottom: 8px;
        }

        .no-data-subtext {
            color: var(--text-muted);
            font-size: 0.95rem;
        }

        .footer {
            text-align: center;
            padding: 20px;
            color: var(--text-muted);
            font-size: 0.9rem;
            border-top: 1px solid var(--border-color);
        }

        .footer-icon {
            margin-right: 8px;
        }

        .loading {
            opacity: 0.7;
            pointer-events: none;
        }

        @media (max-width: 768px) {
            body {
                padding: 10px;
            }

            .title {
                font-size: 1.8rem;
            }

            .date-navigation {
                padding: 12px 20px;
                gap: 15px;
                max-width: 90%;
                flex-direction: column;
            }

            .current-date {
                font-size: 1.1rem;
                min-width: 120px;
            }

            .date-picker-container {
                margin-top: 10px;
            }

            .date-picker {
                font-size: 16px;
                padding: 10px 15px;
            }

            .content {
                padding: 20px;
            }

            .table th,
            .table td {
                padding: 12px 8px;
                font-size: 0.9rem;
            }

            .summary-stats {
                grid-template-columns: 1fr;
            }
        }

        @keyframes fadeIn {
            from { opacity: 0; transform: translateY(20px); }
            to { opacity: 1; transform: translateY(0); }
        }

        .main-container {
            animation: fadeIn 0.6s ease-out;
        }
    </style>
</head>
<body>
    <div class="main-container">
        <div class="header">
            <button class="theme-toggle" onclick="toggleTheme()" title="Toggle Dark/Light Mode">
                <span id="theme-icon">🌙</span>
            </button>

            <h1 class="title">Technical Support Group (Roster)</h1>

            <div class="date-navigation">
                <button class="nav-button" onclick="changeDate('${prevDateStr}')" title="Previous Day">
                    <span>◀</span>
                </button>

                <div class="current-date">${displayDate}</div>

                <button class="nav-button" onclick="changeDate('${nextDateStr}')" title="Next Day">
                    <span>▶</span>
                </button>

                <div class="date-picker-container">
                    <input type="date" 
                           class="date-picker" 
                           value="${selectedDate}" 
                           onchange="changeDate(this.value)"
                           title="Select Date">
                </div>
            </div>
        </div>

        <div class="content">
            <div class="table-container">
                <table class="table">
                    <thead>
                        <tr>
                            <th>#</th>
                            <th>Employee Name</th>
                            <th>Shift</th>
                            <th>Mobile</th>
                            <th>Email</th>
                        </tr>
                    </thead>
                    <tbody id="roster-tbody">
                        ${tableRows}
                    </tbody>
                </table>
            </div>
        </div>

        <div class="footer">
            <span class="footer-icon">⏰</span>
            Last updated: ${istTime}<br>
            Made by Neel
        </div>
    </div>

    <script>
        // Theme Management - Fixed for sandboxed environment with dark mode default
        let currentTheme = 'dark'; // Default to dark theme

        function initializeTheme() {
            // Try to use localStorage, fallback to dark if not available
            try {
                const savedTheme = localStorage.getItem('roster-theme') || 'dark';
                currentTheme = savedTheme;
            } catch (e) {
                // localStorage not available in sandboxed environment
                currentTheme = 'dark';
                console.log('Theme persistence not available in sandboxed environment');
            }
            document.documentElement.setAttribute('data-theme', currentTheme);
            updateThemeIcon(currentTheme);
        }

        function toggleTheme() {
            const newTheme = currentTheme === 'light' ? 'dark' : 'light';
            currentTheme = newTheme;

            document.documentElement.setAttribute('data-theme', newTheme);

            // Try to save to localStorage if available
            try {
                localStorage.setItem('roster-theme', newTheme);
            } catch (e) {
                // localStorage not available, theme will reset on page reload
                console.log('Theme saved in memory only (localStorage not available)');
            }

            updateThemeIcon(newTheme);
        }

        function updateThemeIcon(theme) {
            const icon = document.getElementById('theme-icon');
            icon.textContent = theme === 'light' ? '🌙' : '☀️';
        }

        // G Shift Toggle Functionality
        let gShiftVisible = false;

        function toggleGShift() {
            const gShiftRows = document.querySelectorAll('.g-shift-row');
            const gShiftIcon = document.getElementById('g-shift-icon');
            const gShiftText = document.getElementById('g-shift-text');

            gShiftVisible = !gShiftVisible;

            gShiftRows.forEach(row => {
                row.style.display = gShiftVisible ? 'table-row' : 'none';
            });

            gShiftIcon.textContent = gShiftVisible ? '🙈' : '👁️';
            gShiftText.textContent = gShiftVisible 
                ? 'Hide G Shift (${gShiftCount} employees)' 
                : 'Show G Shift (${gShiftCount} employees)';
        }

        // Date Navigation - Simplified approach for sandboxed environment
        function changeDate(newDate) {
            // Show loading state
            const container = document.querySelector('.main-container');
            container.classList.add('loading');

            console.log('Attempting to navigate to date:', newDate);

            // Since we're in a sandboxed environment, we'll use a different approach
            // We'll construct the full webhook URL and navigate to it
            const webhookBase = 'https://n8n.captainparth.com/webhook/roster';
            const newUrl = webhookBase + '?date=' + encodeURIComponent(newDate);

            console.log('Navigating to:', newUrl);

            // For sandboxed environments, we need to use location.replace or assign
            try {
                // Try location.replace first (doesn't add to history)
                window.location.replace(newUrl);
            } catch (e1) {
                console.log('location.replace failed:', e1.message);
                try {
                    // Try location.assign
                    window.location.assign(newUrl);
                } catch (e2) {
                    console.log('location.assign failed:', e2.message);
                    try {
                        // Try setting location.href directly
                        window.location.href = newUrl;
                    } catch (e3) {
                        console.log('location.href failed:', e3.message);
                        try {
                            // Try document.location
                            document.location = newUrl;
                        } catch (e4) {
                            console.error('All navigation methods failed');

                            // Show user-friendly message with manual option
                            const userChoice = confirm(
                                'Automatic navigation is blocked in this environment.\\n\\n' +
                                'Would you like to open the date ' + newDate + ' in a new tab?\\n\\n' +
                                'Click OK to open in new tab, or Cancel to copy the URL.'
                            );

                            if (userChoice) {
                                // Open in new tab
                                window.open(newUrl, '_blank');
                            } else {
                                // Copy URL to clipboard and show it
                                if (navigator.clipboard) {
                                    navigator.clipboard.writeText(newUrl).then(() => {
                                        alert('URL copied to clipboard:\\n' + newUrl);
                                    }).catch(() => {
                                        alert('Please copy this URL manually:\\n' + newUrl);
                                    });
                                } else {
                                    alert('Please copy this URL manually:\\n' + newUrl);
                                }
                            }

                            // Remove loading state
                            container.classList.remove('loading');
                        }
                    }
                }
            }
        }

        // Initialize theme on page load
        document.addEventListener('DOMContentLoaded', initializeTheme);

        // Add keyboard navigation
        document.addEventListener('keydown', function(e) {
            if (e.key === 'ArrowLeft') {
                changeDate('${prevDateStr}');
            } else if (e.key === 'ArrowRight') {
                changeDate('${nextDateStr}');
            } else if (e.key === 't' || e.key === 'T') {
                toggleTheme();
            }
        });

        // Add smooth scroll for mobile
        if (window.innerWidth <= 768) {
            document.addEventListener('touchstart', function(e) {
                if (e.touches.length > 1) {
                    e.preventDefault();
                }
            }, { passive: false });
        }

        console.log('🚀 Roster Dashboard loaded successfully!');
        console.log('📊 Roster data:', ${JSON.stringify(rosterData?.length || 0)} + ' entries');
        console.log('📅 Current date:', '${selectedDate}');
        console.log('🎨 Theme support enabled');
        console.log('⌨️ Keyboard shortcuts: ← → for navigation, T for theme toggle');
    </script>
</body>
</html>`;

// Return using Code node format with all data
return [{ json: { html: html, selectedDate: selectedDate, employeeCount: employeeCount } }];
